// Block (composition) — a floating bar of mixed controls pinned to the bottom of the viewport.
// Contract: docs/rules/block-contract.md. FloatingToolbar's sibling for a control set a toolbar
// cannot hold: a `role="toolbar"` takes the arrow keys for roving focus (React Aria's useToolbar
// catches ArrowLeft/Right in the capture phase), so a SearchField inside one cannot move its caret.
// This bar has no roving focus: every control keeps its own keys, and Tab walks them.
//   Card    → SURFACE   (size="small" variant="raised", as FloatingToolbar)
//   Stack   → the row, wrapping inside the bar when the controls outgrow the viewport
//   Block   → PLACEMENT (position: fixed on the sticky layer)
// It renders a named `<section>`, so the bar is a region landmark a screen reader can jump to.
// The bar covers the bottom of the page, so it sets the document's `scroll-padding-block-end` to its
// own reach, and a control scrolled into view stops above it (WCAG 2.4.11). It reserves no space in
// flow, so the consumer still keeps room after the page's last content, or the last row can never
// scroll clear of the bar. FloatingToolbar does and needs the same.
// Posture: self-contained floating chrome.
import type { CSSProperties, ReactNode, Ref } from "react";
import { Card } from "../components/Card";
import { useScrollClearance } from "../components/useScrollClearance";
import { Stack } from "../layouts/Stack";
import "./FloatingBar.css";

export interface FloatingBarProps {
  /** The controls: fields, Selects, a SegmentedControl, Buttons. Each is chrome owned by a bar,
   *  so pass them at `size="small"` (prop-usage-contract.md § Size, row chrome). */
  children?: ReactNode;
  /** Accessible name for the bar's region. Required: the bar has no visible heading. */
  "aria-label": string;
  /** The horizontal span the bar centres within, as CSS inline insets (`"600px 24px"`). Omit for
   *  the viewport. The same seam FloatingToolbar takes. */
  insetInline?: string;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function FloatingBar({
  children,
  "aria-label": ariaLabel,
  insetInline,
  className,
  ref,
}: FloatingBarProps) {
  const clearRef = useScrollClearance("end", ref);
  return (
    <section
      ref={clearRef}
      aria-label={ariaLabel}
      style={
        insetInline
          ? ({ "--sd-layout-floating-bar-inline": insetInline } as CSSProperties)
          : undefined
      }
      className={className ? `sd-floatingbar ${className}` : "sd-floatingbar"}
    >
      {/* `raised` because the bar floats over page content; `small` because it IS a bar. */}
      <Card size="small" variant="raised" className="sd-floatingbar__bar">
        {/* spacing: action-row — the controls are one unit of peers, as a toolbar's are */}
        <Stack direction="row" gap="x-small" align="center" wrap className="sd-floatingbar__row">
          {children}
        </Stack>
      </Card>
    </section>
  );
}

/* FloatingBar.css — .sd-floatingbar (Block)
   Arrangement only: pin the bar to the bottom centre of the viewport, as FloatingToolbar.css does.
   The surface is the composed Card's, the row the composed Stack's. References Sys layout scales
   only; defines no tokens. */
.sd-floatingbar {
  position: fixed;
  /* The span the bar centres within, as inline insets; `0` is the viewport. Declared `initial` so
     it cannot inherit from an ancestor: it comes through the `insetInline` prop. */
  --sd-layout-floating-bar-inline: initial;
  inset-inline: var(--sd-layout-floating-bar-inline, 0);
  inset-block-end: var(--sd-overlay-margin-medium);
  display: flex;
  justify-content: center;
  z-index: var(--sd-layer-sticky);
  /* Clicks fall through the transparent gutter beside the bar; the bar re-enables them. */
  pointer-events: none;
}

.sd-floatingbar__bar {
  pointer-events: auto;
  /* Hug the controls, never wider than the viewport gutter allows; past that the Stack wraps. */
  width: max-content;
  max-width: calc(100% - 2 * var(--sd-overlay-margin-medium));
}
